namespace SchoolOS.Application.Common;

/// <summary>
/// Abstraction over the binary file store used for uploads (student documents, and later
/// homework attachments). Paths are relative identifiers generated by the application;
/// the implementation resolves them safely inside its configured root.
/// </summary>
public interface IFileStorage
{
    Task SaveAsync(Stream content, string relativePath, CancellationToken cancellationToken = default);

    /// <summary>Opens a stored file for reading, or returns null when it does not exist.</summary>
    Task<Stream?> OpenReadAsync(string relativePath, CancellationToken cancellationToken = default);

    Task DeleteAsync(string relativePath, CancellationToken cancellationToken = default);
}
